BASE={
 'q-32234':[[1,1,2,19],[3,1,2,31]], 'q-42040':[[1,0,3,-2],[1,1,0,0]],
 'q-131715':[[1,-1,2,2],[1,0,-3,1]],'q-131717':[[1,3,1,-1],[-2,-5,0,3]],
